const record = $json.record || $json;
const f = record.fields || {};

const existingDocumentId = String(
  f['SignWell Document ID'] || ''
).trim();

let dispatchAction = '';

try {
  dispatchAction = String(
    $('Agreement Dispatcher').item.json.body?.action || ''
  ).trim();
} catch {}

const allowedActions = [
  '',
  'Create SignWell Draft',
  'Send SignWell Agreement',
];

if (!allowedActions.includes(dispatchAction)) {
  throw new Error(
    'Unsupported agreement action: ' + dispatchAction
  );
}

if (
  dispatchAction === 'Create SignWell Draft' &&
  existingDocumentId
) {
  throw new Error(
    'A SignWell draft already exists for this record.'
  );
}

if (
  dispatchAction === 'Send SignWell Agreement' &&
  !existingDocumentId
) {
  throw new Error(
    'A SignWell Document ID is required before sending.'
  );
}

const shouldSend =
  dispatchAction === 'Send SignWell Agreement' ||
  (
    !dispatchAction &&
    Boolean(f['Send SignWell Agreement']) &&
    Boolean(existingDocumentId)
  );

if (shouldSend) {
  return [
    {
      json: {
        action: 'send',
        airtableRecordId: record.id,
        documentId: existingDocumentId,
        requestUrl:
          'https://www.signwell.com/api/v1/documents/' +
          existingDocumentId +
          '/send',
        signwellBody: {
          test_mode: false,
        },
      },
    },
  ];
}

const agreementType = String(
  f['Agreement Type'] || ''
).trim();

const normalizedAgreementType =
  agreementType.toLowerCase();

const isMonthly = [
  'retainer',
  'monthly investment',
].includes(normalizedAgreementType);

const isPpl = [
  'ppl',
  'pay per qualified call',
].includes(normalizedAgreementType);

if (!isMonthly && !isPpl) {
  throw new Error(
    'Agreement Type must be Retainer or PPL.'
  );
}

const commonRequired = {
  'Agreement Type': agreementType,
  'Company Name': f['Company Name'],
  'First Name': f['First Name'],
  'Last Name': f['Last Name'],
  Email: f['Email'],
  'Reference Number': f['Reference Number'],
  'Company Address': f['Company Address'],
  'Start Date': f['Start Date'],
};

const pricingRequired = isMonthly
  ? {
      'Monthly Investment':
        f['Monthly Investment'],
    }
  : {
      'Monthly Technology Fee':
        f['Monthly Technology Fee'],
      'Price Per Qualified Call':
        f['Price Per Qualified Call'],
    };

const required = {
  ...commonRequired,
  ...pricingRequired,
};

const missing = Object.entries(required)
  .filter(([, value]) => {
    return (
      value === undefined ||
      value === null ||
      String(value).trim() === ''
    );
  })
  .map(([key]) => key);

if (missing.length) {
  throw new Error(
    'Missing required Airtable fields: ' +
      missing.join(', ')
  );
}

const company = String(
  f['Company Name']
).trim();

const clientName = (
  String(f['First Name']).trim() +
  ' ' +
  String(f['Last Name']).trim()
).trim();

const email = String(
  f['Email']
).trim();

const address = String(
  f['Company Address']
).trim();

const referenceId = String(
  f['Reference Number']
).trim();

const agreementDate =
  new Date().toLocaleDateString('en-US', {
    timeZone: 'America/New_York',
  });

const startDate = new Date(
  String(f['Start Date']) + 'T12:00:00Z'
).toLocaleDateString('en-US', {
  timeZone: 'UTC',
});

const additionalServices = [
  f['LinkedIn'] ? 'LinkedIn' : '',
  f['AI / Cold Caller'] ? 'AI / Cold Caller' : '',
  f['Direct Mail'] ? 'Direct Mail' : '',
]
  .filter(Boolean)
  .join(', ') || '\u200B';

const currency = String(
  f['Agreement Currency'] || 'USD'
)
  .trim()
  .toUpperCase();

const currencySymbols = {
  USD: '$',
  GBP: '£',
  EUR: '€',
};

const currencySymbol =
  currencySymbols[currency] || currency + ' ';

const money = (value) => {
  return (
    currencySymbol +
    Number(value).toLocaleString('en-US', {
      minimumFractionDigits: 2,
      maximumFractionDigits: 2,
    })
  );
};

const templateFields = [
  {
    api_id: 'COMPANY',
    value: company,
  },
  {
    api_id: 'ADDRESS',
    value: address,
  },
  {
    api_id: 'Agreement_Date',
    value: agreementDate,
  },
  {
    api_id: 'add_services',
    value: additionalServices,
  },
  {
    api_id: 'name2',
    value: clientName,
  },
  {
    api_id: 'company2',
    value: company,
  },
  {
    api_id: 'start_date',
    value: startDate,
  },
];

if (isPpl) {
  templateFields.unshift({
    api_id: 'NAME',
    value: clientName,
  });
}

if (isMonthly) {
  templateFields.unshift({
    api_id: 'Name',
    value: clientName,
  });

  templateFields.push(
    {
      api_id: 'ref_ID',
      value: referenceId,
    },
    {
      api_id: 'investment',
      value: money(f['Monthly Investment']),
    },
    {
      api_id: 'td_date',
      value: agreementDate,
    }
  );
} else {
  const ppc = money(
    f['Price Per Qualified Call']
  );

  const techFee = money(
    f['Monthly Technology Fee']
  );

  templateFields.push(
    {
      api_id: 'ref_ID',
      value: referenceId,
    },
    {
      api_id: 'ref_ID2',
      value: referenceId,
    },
    {
      api_id: 'ppc',
      value: ppc,
    },
    {
      api_id: 'tech_fee',
      value: techFee,
    },
    {
      api_id: 'tech_fee2',
      value: techFee,
    },
    {
      api_id: 'ppc2',
      value: ppc,
    },
    {
      api_id: 'ppc3',
      value: ppc,
    },
    {
      api_id: 'td_date',
      value: agreementDate,
    },
    {
      api_id: 'td_date2',
      value: agreementDate,
    }
  );
}

const templateId = isMonthly
  ? 'fd4e95ca-23b6-4a12-a81e-500796acb55a'
  : '4135ea10-93b8-483a-a94b-2df6401e1334';

const signwellBody = {
  test_mode: false,
  template_id: templateId,
  name:
    company +
    ' <> Dulcy | Growth Partnership',
  subject:
    'Dulcy Growth Partnership Agreement',
  message:
    'Please review and sign your Dulcy Growth Partnership Agreement.',
  recipients: [
    {
      id: '1',
      placeholder_name: 'Client',
      name: clientName,
      email,
    },
  ],
  draft: true,
  reminders: true,
  allow_decline: true,
  allow_reassign: true,
  template_fields: templateFields,
  metadata: {
    airtable_record_id: record.id,
    agreement_type: agreementType,
    reference_id: referenceId,
    currency,
  },
};

signwellBody.recipients.push({
  id: '2',
  placeholder_name: 'Dulcy',
  name: 'Alexander Woung',
  email: 'scale@dulcy.io',
});

return [
  {
    json: {
      action: 'create',
      airtableRecordId: record.id,
      company,
      clientName,
      email,
      agreementType,
      currency,
      requestUrl:
        'https://www.signwell.com/api/v1/document_templates/documents',
      signwellBody,
    },
  },
];

const payload = $json.body || $json;
const eventName = payload.event?.type || payload.event?.name || payload.event || payload.type;
const doc = payload.data?.object || payload.data || payload.object || payload.document || {};
const documentId = doc.id || payload.document_id;
if (!eventName || !documentId) throw new Error('SignWell webhook missing event type or document ID');
const eventTime = payload.event?.created_at || payload.created_at || new Date().toISOString();
const statusMap = {
  document_created: 'Draft', document_sent: 'Sent', document_viewed: 'Viewed', document_in_progress: 'Viewed',
  document_completed: 'Completed', document_declined: 'Declined', document_expired: 'Expired',
  document_canceled: 'Declined', document_bounced: 'Error', document_error: 'Error'
};
return [{ json: { eventName: String(eventName), documentId: String(documentId), eventTime, status: statusMap[eventName] || null, payload, document: doc } }];

const event = $('Normalize SignWell Event').item.json;
const record = ($json.records || [])[0];
if (!record) throw new Error(`No Airtable agreement found for SignWell document ${event.documentId}`);
const fields = { 'SignWell Last Event': event.eventName, 'Last SignWell Sync': new Date().toISOString() };
if (event.status) fields['Agreement Status'] = event.status;
if (event.eventName === 'document_sent') fields['SignWell Sent At'] = event.eventTime;
if (event.eventName === 'document_viewed' || event.eventName === 'document_in_progress') fields['SignWell Viewed At'] = event.eventTime;
if (event.eventName === 'document_completed') fields['SignWell Completed At'] = event.eventTime;
if (['document_error','document_bounced'].includes(event.eventName)) fields['SignWell Error'] = JSON.stringify(event.payload).slice(0, 9000);
return [{ json: { airtableRecordId: record.id, existingFields: record.fields || {}, updateFields: fields, isCompleted: event.eventName === 'document_completed', documentId: event.documentId, completedPdfUrl: event.document.completed_pdf_url || null, eventPayload: event.payload } }];

